CREATE INDEX "audit_events_channel_created_idx" ON "audit_events" USING btree ("organization_id","created_at" DESC NULLS LAST,"id" DESC NULLS LAST) WHERE "audit_events"."action" = 'channel.inbound.processed' AND "audit_events"."subject_type" = 'channel_account';--> statement-breakpoint
CREATE INDEX "audit_events_channel_account_created_idx" ON "audit_events" USING btree ("organization_id","subject_id","created_at" DESC NULLS LAST,"id" DESC NULLS LAST) WHERE "audit_events"."action" = 'channel.inbound.processed' AND "audit_events"."subject_type" = 'channel_account';--> statement-breakpoint
CREATE INDEX "audit_events_channel_outcome_created_idx" ON "audit_events" USING btree ("organization_id",("evidence"->>'outcome'),"created_at" DESC NULLS LAST,"id" DESC NULLS LAST) WHERE "audit_events"."action" = 'channel.inbound.processed' AND "audit_events"."subject_type" = 'channel_account';